logic:
team  = player.info.team        // PlayerState+0x930, 0 또는 1
enemy = 1 - team
cache = data.cache              // OperationData+0x00, &AbstractGameWithCache
ctx   = data.context            // OperationData+0x08, &GameContext

// --- 게이트 1 (544줄)
if !rule_scope::line_exists(ctx, line) { return false }

// --- 게이트 2 (549줄) : 좌항 먼저 평가되는 단축평가 2개
//  (2-a) 튜토리얼/시나리오 게이트 — rule_scope::morgard_exists(rule_scope.rs:46) 이 인라인됨.
//        그 안에서 TutorialType::spawn_epic(runner.rs:263) 이 다시 인라인되어
//        `(ctx.tutorial - 1) <u 6` 한 줄만 남았다.
if (ctx.tutorial as u8).wrapping_sub(1) < 6 { return false }   // tutorial ∈ {First,TopSolo,Bottom,MidSolo,MidBottom,JungleOnly}
//  (2-b) 상대 팀 에픽(모르가드) 미니언 버프가 남아 있어야 한다
let moba = cache.game.vtable[0x40]()      // GameMode 반환 {i64 태그, ptr 페이로드}
                 .as_moba().unwrap()      // 태그 워드 != 0 이면 core::option::unwrap_failed 패닉
if moba.epic_minion_buff_time[enemy] == 0 { return false }     // MobaMode+0x240 + enemy*8

// --- 타워 선정 (553~565줄)
let tower_opt: Option<&Entity> =
    cache.tower(line, team)                       // simulation.rs:1822 인라인
        //  = <line>_tower[team].or(<line>_tower2[team])
        //    Top 0x180/0x190 · Mid 0x1a0/0x1b0 · Bottom 0x1c0/0x1d0
    .or(                                          // 554줄, Option::or (eager)
        cache.twin_towers[team]                   // 0x130 + team*32, bumpalo Vec<&Entity>
            .iter()
            .min_by_key(|e| {                     // 555줄 (closure$0 본문 556~557줄)
                 let (sx, sy) = line.get_start_position(ctx.setting, team);   // 556줄
                 game_core::utils::distance_sq(e.x, e.y, sx, sy)              // 557줄
                 //  = |e.x-sx|^2 + |e.y-sy|^2 (abs_diff 2회 → 제곱합)
             })
            .map(|e| *e)                          // 559줄, Option::map(closure$1) = &&Entity → &Entity
    );
// 560~564줄(정확한 소스형태 미확인): None 이면 return false
if tower_opt.is_none() { return false }
let tower = tower_opt.unwrap();                   // 565줄

// --- 게이트 3 (567줄)
if !has_line_defense_threat(player, data, line, tower.id) { return false }   // tower.id = Entity+0x5c0

// --- 타워 근처 적 챔피언 수 (571~572줄)
let champs = cache.champions(enemy, ctx.pool);    // bumpalo Vec<&Entity>, 함수 끝에서 drop
let near_enemy_champion = champs.iter().filter(|c| {          // 572줄 (closure$2)
        data.blackboard[enemy].is_recent_visible(cache.game, player, c)   // && 단축평가
     && c.distance_sq(tower) < 40000000001                    // entity.rs:2157 인라인, 거리 ≤ 200000
    }).count();

// --- 최종 판정 (575~578줄)
let defense = player.strategy(rnd, cache.game).morgard_defense;   // 575~576줄, Strategy+0x0e
return match defense {                                            // 578줄, select 로 접힘
    Battle(1) => (near_enemy_champion - 1) <u 2,   // 근접 적 1명 또는 2명일 때만 true
    Gather(0) => near_enemy_champion > 1,          // 근접 적 2명 이상이면 true
};

// 반환 false 로 빠지는 경로 5개(19번 블록 phi): line_exists 실패 / tutorial 게이트 /
// epic 버프 0 / 타워 후보 없음 / has_line_defense_threat 실패.
// 마지막 1개만 578줄 계산값(%173)을 그대로 반환한다.
